{
  "bioavailability_prediction": "high",
  "claims": [
    {
      "card_ids": ["C59"],
      "claim": "Zalcitabine, a dideoxynucleoside with a small polar nucleoside scaffold, had 88% absolute oral bioavailability in patients, directly supporting F≥20% for the query.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C14"],
      "claim": "Lamivudine, a related nucleoside reverse-transcriptase inhibitor, showed 86–88% absolute oral bioavailability in HIV patients, indicating efficient oral absorption in this chemical class.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C44"],
      "claim": "Emtricitabine, a close cytidine analog, had 93% mean absolute oral bioavailability in HIV-infected subjects, supporting high oral bioavailability for the query's nucleoside framework.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C42"],
      "claim": "Cladribine, a chlorinated purine nucleoside, had estimated oral bioavailability of 45.6% from a tablet, still well above the 20% threshold.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C33"],
      "claim": "Temozolomide, a small heterocyclic drug in the same transfer range, showed ~100% oral bioavailability, supporting that small polar heterocycles can be completely absorbed.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C36"],
      "claim": "Didanosine, a purine dideoxynucleoside, had median F of 0.19 under fed conditions, an affirmative low-bioavailability example; however, this is tied to acid lability and food effects not shared by the query's carbocyclic guanine scaffold.",
      "evidence_role": "contradictory"
    }
  ],
  "confidence": "high",
  "decision_summary": "The query is a polar carbocyclic guanine nucleoside analog. The closest high-transfer nucleoside analogs (zalcitabine, lamivudine, emtricitabine, cladribine) consistently show absolute oral bioavailability well above 20%, mostly 40–93%. The only sub-20% evidence is didanosine under fed conditions, a known acid-labile purine dideoxynucleoside with food-dependent absorption; this liability is not expected to dominate in the query's carbocyclic guanine structure. Therefore high F≥20% is predicted.",
  "evidence_gaps": [
    "No direct human absolute bioavailability measurement for the exact query molecule.",
    "No data on acid stability, intestinal permeability, or transporter/efflux behavior for the query.",
    "Food effects and formulation dependence are unknown for the query."
  ],
  "new_evidence_assessment": [],
  "revision_action": "initial"
}

